<script lang="ts">
let { class: classProp = "" }: { class?: string } = $props();

// Generated from an isometric model; one block never lands, the way a missing page never loads.
const M = {
	W: 620,
	H: 440,
	COUNT: 5,
	DROP: 46,
	zAxis: [0, -1.78],
	P: { origin: [284.96, 229.12], scale: 1.620987134211444, azimuth: 40, elevation: 30 },
	DIAL: { x: 124, y: 32, r: 10, z: 16.2 },
	PER_TURN: 6,
} as const;
const MISSING = 2;

let stage = $state<HTMLElement>();
let needle = $state<SVGPathElement>();
const blocks = $state<SVGGElement[]>([]);

// The kit's isometric camera, so the needle is drawn in the dial's own plane.
function iso(x: number, y: number, z: number): [number, number] {
	const { origin, scale, azimuth, elevation } = M.P;
	const a = (azimuth * Math.PI) / 180;
	const e = (elevation * Math.PI) / 180;
	const k = scale * Math.sqrt(1.6);
	return [
		origin[0] + (x * Math.sin(a) - y * Math.cos(a)) * k,
		origin[1] + ((x * Math.cos(a) + y * Math.sin(a)) * Math.sin(e) - z * Math.cos(e)) * k,
	];
}

function needlePath(turns: number) {
	const turn = turns * Math.PI * 2;
	const { x, y, r, z } = M.DIAL;
	const [ax, ay] = iso(x - Math.sin(turn) * 2.6, y + Math.cos(turn) * 2.6, z);
	const [bx, by] = iso(x + Math.sin(turn) * r, y - Math.cos(turn) * r, z);
	return `M${ax.toFixed(1)} ${ay.toFixed(1)}L${bx.toFixed(1)} ${by.toFixed(1)}`;
}

$effect(() => {
	if (!stage) return;
	const still = matchMedia("(prefers-reduced-motion: reduce)");
	let frame = 0;
	let visible = false;
	let start = 0;

	// Placed blocks sit still; the missing one hovers over its seat, the needle keeps searching.
	function draw(seconds: number) {
		blocks.forEach((block, i) => {
			const z = i === MISSING ? 28 + Math.sin((seconds / 3.4) * Math.PI * 2) * 5 : 0;
			block?.setAttribute("transform", `translate(${M.zAxis[0] * z} ${M.zAxis[1] * z})`);
			block?.setAttribute("opacity", i === MISSING ? "0.9" : "1");
		});
		needle?.setAttribute("d", needlePath(seconds / 9));
	}

	function tick(now: number) {
		start ||= now;
		draw((now - start) / 1000);
		frame = visible ? requestAnimationFrame(tick) : 0;
	}

	const observer = new IntersectionObserver(
		(entries) => {
			visible = entries[entries.length - 1]?.isIntersecting ?? false;
			if (still.matches) return draw(0);
			if (visible && !frame) frame = requestAnimationFrame(tick);
		},
		{ rootMargin: "120px 0px" },
	);
	observer.observe(stage);
	return () => {
		observer.disconnect();
		cancelAnimationFrame(frame);
	};
});
</script>

